#!/usr/bin/env python3
"""Self-contained launcher for the v4.1 provenance-mutation test.

Run with no arguments to execute the harness. Use --extract PATH to write the
readable source-copy harness. The expanded source SHA-256 is verified first.
"""
import base64, gzip, hashlib, sys
from pathlib import Path

EXPECTED_SHA256 = "504d8240518165e142f553f29b01dbe307d22b1528b21af5c6f87c23ed9d42ea"
PAYLOAD = (
""
)
source = gzip.decompress(base64.b64decode("".join(PAYLOAD).encode("ascii")))
observed = hashlib.sha256(source).hexdigest()
if observed != EXPECTED_SHA256:
    raise SystemExit(f"expanded source hash mismatch: {observed}")
if len(sys.argv) == 3 and sys.argv[1] == "--extract":
    target = Path(sys.argv[2])
    target.write_bytes(source)
    print(f"EXTRACTED={target}")
    print(f"EXPANDED_SOURCE_SHA256={observed}")
elif len(sys.argv) == 1:
    exec(compile(source, "AIEFS_Part4_v41_provenance_mutations.py", "exec"),
         {"__name__": "__main__", "__file__": "AIEFS_Part4_v41_provenance_mutations.py"})
else:
    raise SystemExit("usage: reproducer.py [--extract PATH]")
